import base64
import json

texto_base64 = ""




# Remove espaços, quebras de linha acidentais e corrige padding
texto_base64 = texto_base64.strip()
texto_base64 += "=" * (-len(texto_base64) % 4)

# Decodifica Base64
json_texto = base64.b64decode(texto_base64).decode("utf-8")

# Converte JSON para dicionário Python
dados = json.loads(json_texto)

# Salva o conteúdo desserializado em arquivo JSON formatado
with open("cursoClaudeDesignEssentials.json", "w", encoding="utf-8") as arquivo:
    json.dump(dados, arquivo, ensure_ascii=False, indent=2)

print("Arquivo JSON gerado com sucesso: cursoClaudeDesktopHandsOn.json")
print(dados.keys())

# Exemplo de acesso ao título, se existir
print(dados["course"]["title"])